INSERT OR IGNORE INTO problems (slug, title, body, difficulty, tags, starter, cases, solution, source_url, status, created_by) VALUES ('hello-panther', 'Hello, Panther', 'Every duel night opens with a warm-up. Read a name and greet it.

## Input

One line with a name.

## Output

Print `Hello, NAME!` where NAME is the name exactly as it was given.

## Constraints

- The name has 1 to 30 characters: letters, spaces, hyphens and apostrophes.
- The name does not start or end with a space.

## Sample input

```
Panther
```

## Sample output

```
Hello, Panther!
```', 1, 'duel,duel-pack-1', '{"java":"import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n        String name = in.readLine();\n        // print the greeting\n    }\n}\n","python":"name = input()\n# print the greeting\n"}', '[{"stdin":"Panther\n","stdout":"Hello, Panther!"},{"stdin":"Ana\n","stdout":"Hello, Ana!"},{"stdin":"Mary Jane\n","stdout":"Hello, Mary Jane!"},{"stdin":"O''Neil\n","stdout":"Hello, O''Neil!"},{"stdin":"Jean-Luc\n","stdout":"Hello, Jean-Luc!"},{"stdin":"Q\n","stdout":"Hello, Q!"},{"stdin":"Maximiliana Dorothea Clementin\n","stdout":"Hello, Maximiliana Dorothea Clementin!"},{"stdin":"de la Cruz\n","stdout":"Hello, de la Cruz!"},{"stdin":"ALEXANDER\n","stdout":"Hello, ALEXANDER!"},{"stdin":"Ngozi Adaeze-Okafor\n","stdout":"Hello, Ngozi Adaeze-Okafor!"}]', 'name = input()
print(f"Hello, {name}!")
', '', 'live', 'pack-seed');
INSERT OR IGNORE INTO problems (slug, title, body, difficulty, tags, starter, cases, solution, source_url, status, created_by) VALUES ('box-score', 'Box score', 'The scorebook lists how many points each player scored in tonight''s basketball game. Print the team''s total.

## Input

The first line has N, the number of players. The second line has N integers separated by spaces: the points each player scored.

## Output

Print one integer: the sum of all N scores.

## Constraints

- 1 ≤ N ≤ 1,000
- Each score is between 0 and 1,000.

## Sample input

```
5
12 0 7 21 3
```

## Sample output

```
43
```', 1, 'duel,duel-pack-1', '{"java":"import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n        int n = Integer.parseInt(in.readLine().trim());\n        StringTokenizer st = new StringTokenizer(in.readLine());\n        // read n scores with Integer.parseInt(st.nextToken()), add them up, print the total\n    }\n}\n","python":"n = int(input())\nscores = list(map(int, input().split()))\n# add up the scores and print the total\n"}', '[{"stdin":"5\n12 0 7 21 3\n","stdout":"43"},{"stdin":"1\n0\n","stdout":"0"},{"stdin":"1\n1000\n","stdout":"1000"},{"stdin":"3\n0 0 0\n","stdout":"0"},{"stdin":"2\n4 9\n","stdout":"13"},{"stdin":"10\n18 27 6 29 30 17 29 11 14 1\n","stdout":"182"},{"stdin":"7\n0 15 0 0 8 0 22\n","stdout":"45"},{"stdin":"1000\n679 515 219 616 227 939 295 497 709 801 217 336 994 448 72 261 197 164 90 455 788 550 375 196 483 805 333 244 652 810 413 432 213 64 440 478 311 216 113 667 843 639 696 336 680 879 903 273 404 801 388 234 433 78 414 762 684 428 6 892 475 221 547 96 353 814 22 379 721 368 9 268 577 839 157 35 442 185 284 67 781 154 414 701 745 847 371 917 668 582 486 170 510 864 896 522 318 889 890 185 707 543 699 893 6 976 86 67 32 589 354 547 968 718 896 452 858 836 121 692 722 624 793 619 828 471 811 652 143 702 183 946 811 205 755 955 913 560 457 998 910 991 142 83 980 153 905 319 345 384 69 61 561 563 705 358 474 58 197 285 695 844 335 92 286 959 157 256 477 209 435 114 536 819 922 982 326 250 97 287 668 1000 908 180 12 14 648 404 877 627 469 671 583 45 823 344 244 809 279 482 676 200 565 607 548 322 342 18 959 136 295 353 695 373 915 412 410 653 55 762 225 528 67 221 151 680 123 149 350 124 378 24 458 880 681 207 692 687 703 842 373 525 678 641 563 213 130 469 558 569 325 307 692 308 752 261 246 903 445 208 465 997 304 769 41 251 50 592 350 757 899 449 449 682 52 275 566 727 209 973 34 791 