INSERT OR IGNORE INTO problems (slug, title, body, difficulty, tags, starter, cases, solution, source_url, status, created_by) VALUES ('win-streak', 'Longest win streak', 'The tennis team writes its season record as a string: W for a win and L for a loss, in the order the matches were played. What was the team''s longest run of wins in a row?

## Input

One line made of the letters W and L.

## Output

Print the length of the longest run of consecutive W. Print 0 if there are no wins at all.

## Constraints

- The line has 1 to 100,000 letters.
- Every letter is W or L.

## Sample input 1

```
WWLWWWLW
```

## Sample output 1

```
3
```

## Sample input 2

```
LLL
```

## Sample output 2

```
0
```', 2, 'duel,duel-pack-1', '{"java":"import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n        String record = in.readLine().trim();\n        int best = 0;\n        int run = 0;\n        for (int i = 0; i < record.length(); i++) {\n            // a W makes the current run longer; an L ends it\n        }\n        System.out.println(best);\n    }\n}\n","python":"record = input().strip()\nbest = 0\nrun = 0\nfor game in record:\n    # a W makes the current run longer; an L ends it\n    pass\nprint(best)\n"}', '[{"stdin":"WWLWWWLW\n","stdout":"3"},{"stdin":"LLL\n","stdout":"0"},{"stdin":"W\n","stdout":"1"},{"stdin":"L\n","stdout":"0"},{"stdin":"WLWLWL\n","stdout":"1"},{"stdin":"LLLWWWW\n","stdout":"4"},{"stdin":"WWWWLLL\n","stdout":"4"},{"stdin":"\n","stdout":"19"},{"stdin":"\n","stdout":"2000"}]', 'record = input().strip()
best = 0
run = 0
for game in record:
    if game == "W":
        run += 1
        best = max(best, run)
    else:
        run = 0
print(best)
