INSERT OR IGNORE INTO problems (slug, title, body, difficulty, tags, starter, cases, solution, source_url, status, created_by) VALUES ('name-tag', 'Name tag', 'Warm-up: print a name tag for the club fair. Read a first name and a grade, and print them in the tag format.

## Input

The first line has a first name. The second line has the grade, a whole number.

## Output

Print `NAME, grade G` where NAME is the name and G is the grade. For example, `Maya, grade 10`.

## Constraints

- The name has 1 to 20 letters.
- 9 ≤ G ≤ 12

## Sample input

```
Maya
10
```

## Sample output

```
Maya, grade 10
```', 1, 'duel,duel-pack-2', '{"java":"import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n        String name = in.readLine().trim();\n        int grade = Integer.parseInt(in.readLine().trim());\n        // print the tag, for example: Maya, grade 10\n    }\n}\n","python":"name = input().strip()\ngrade = int(input())\n# print the tag, for example: Maya, grade 10\n"}', '[{"stdin":"Maya\n10\n","stdout":"Maya, grade 10"},{"stdin":"Leo\n9\n","stdout":"Leo, grade 9"},{"stdin":"Ana\n12\n","stdout":"Ana, grade 12"},{"stdin":"X\n11\n","stdout":"X, grade 11"},{"stdin":"Bartholomewsonnworth\n9\n","stdout":"Bartholomewsonnworth, grade 9"},{"stdin":"Priya\n11\n","stdout":"Priya, grade 11"},{"stdin":"JOSE\n10\n","stdout":"JOSE, grade 10"},{"stdin":"Kwame\n12\n","stdout":"Kwame, grade 12"},{"stdin":"Mei\n9\n","stdout":"Mei, grade 9"}]', 'name = input().strip()
grade = int(input())
print(f"{name}, grade {grade}")
', '', 'live', 'pack-seed');
INSERT OR IGNORE INTO problems (slug, title, body, difficulty, tags, starter, cases, solution, source_url, status, created_by) VALUES ('top-score', 'Top score', 'The quiz is graded. Find the highest score in the class and how many students got it.

## Input

The first line has N, the number of students. The second line has N scores separated by spaces.

## Output

Print two integers on one line, separated by a space: the highest score, then how many students got that score.

## Constraints

- 1 ≤ N ≤ 1,000
- Each score is a whole number from 0 to 100.

## Sample input

```
6
88 92 75 92 60 81
```

## Sample output

```
92 2
```', 1, 'duel,duel-pack-2', '{"java":"import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n        int n = Integer.parseInt(in.readLine().trim());\n        StringTokenizer st = new StringTokenizer(in.readLine());\n        // read n scores with Integer.parseInt(st.nextToken())\n        // find the highest score, then count how many times it appears\n    }\n}\n","python":"n = int(input())\nscores = list(map(int, input().split()))\n# find the highest score, then count how many times it appears\n"}', '[{"stdin":"6\n88 92 75 92 60 81\n","stdout":"92 2"},{"stdin":"1\n70\n","stdout":"70 1"},{"stdin":"4\n0 0 0 0\n","stdout":"0 4"},{"stdin":"3\n100 99 98\n","stdout":"100 1"},{"stdin":"4\n50 60 70 80\n","stdout":"80 1"},{"stdin":"12\n65 65 65 65 65 65 65 65 65 65 65 65\n","stdout":"65 12"},{"stdin":"1000\n63 12 54 35 73 50 61 40 23 39 85 56 23 15 91 86 83 9 96 33 86 13 67 90 1 84 63 95 9 38 1 85 12 20 36 66 29 67 51 21 59 45 49 84 34 2 50 19 76 47 20 79 12 96 59 31 42 34 39 38 64 93 66 61 42 76 47 89 70 94 95 6 75 54 13 0 85 88 55 22 37 73 72 39 80 6 74 0 76 73 84 33 48 25 78 16 42 23 65 7 7 74 92 20 56 83 38 84 57 86 50 0 65 3 3 8 2 90 36 67 25 62 61 99 86 2 41 16 67 13 41 58 14 6 58 29 31 97 3 23 0 49 9 58 5 20 0 60 95 42 8 72 22 46 33 71 57 0 30 90 15 19 74 53 35 52 23 48 55 91 46 80 100 42 67 24 85 35 1 11 43 57 43 16 60 12 21 18 30 75 47 24 26 53 3 50 37 33 33 55 35 92 13 25 26 20 20 20 67 64 39 8 1 53 1 21 68 8 37 71 24 54 92 62 46 77 42 59 99 5 93 86 34 69 51 94 35 62 88 7 60 2 95 50 93 84 18 80 53 71 3 45 93 62 1 51 86 20 20 23 85 63 54 68 52 67 47 69 49 8 58 37 92 66 57 53 12 74 0 100 43 27 67 18 67 3 62 78 91 7 23 28 95 28 31 19 55 100 0 30 55 41 100 58 70 19 34 34 14 27 7 82 83 90 70 68 71 24 19 77 31 94 38 20 100 47 29 88 89 80 35 37 32 25 84 85 66 14 50 30 100 22 23 75 8 39 60 72 94 36 17 50 71 99 21 74 99 